_DB = [("Father", "Anak, mukhang humuhusay ka na sa target practice at mukhang gumaganda at lumalakas na rin ang katawan mo.", "Son, it seems you are getting better at target practice and your body is also looking better and getting stronger."), ("Son", "Naghahanda lang po. Interesado po akong mag-apply sa PNPA. Gusto ko po sanang maging pulis.", "I’m just preparing. I’m interested in applying to the PNPA. I would like to become a policeman."), ("Father", "Magiging magaling ka nga kung palagi kang nagsasanay.", "You will indeed become good if you train regularly."), ("Son", "Tatay, hindi kaya tututol si Nanay sa plano kong maging pulis?", "Father, wouldn’t Mother object to my plan to become a policeman?"), ("Father", "Hindi naman siguro. Maging si Lolo Jorge mo, ama ng ina mo, ay isang kilalang pulis. Maging ang nasira mong lolo sa tuhod ay isa ring pulis. Pareho silang matapat at walang kinatatakutan.", "Probably not. Even your Grandpa Jorge, your mother’s father, was a well-known policeman. Even your late great-grandfather was also a policeman. They were both honest and feared no one."), ("Son", "Hindi ho kaya mahirap ang pagsasanay pisikal sa loob ng akademya?", "Wouldn’t the physical training inside the academy be hard?"), ("Father", "Magiging mahirap lang ang kahit anong bagay kung iisipin mong mahirap ito. Alam mo ba ’yung kababata ko na lalampa-lampa ay nagtapos sa PNPA? Maging ako ay nagulat nung nalaman ko.", "Anything will only become hard if you think it is hard. Do you know my childhood friend who was weak and feeble graduated from the PNPA? Even I was surprised when I learned it."), ("Son", "Salamat, ’Tay sa payo n’yo. Sana’y maging tulad ako ng kababata n’yo at nila Lolo. Sana’y maging mahusay na pulis din ako.", "Thank you, Dad, for your advice. I hope I become like your childhood friend and like Grandpa. I hope I also become a good policeman."), ("Father", "Sana nga anak. Sana maging huwaran ka sa anumang mapili mong propesyon.", "I hope so, son. I hope you become a role model in whatever profession you choose.")]
_VB = [("mukha", "it seems, it looks like"), ("magiging", "will become"), ("palagi", "always, often, on a regular basis"), ("lolo sa tuhod", "great grandfather"), ("bagay", "things"), ("kababata", "childhood friend"), ("nagulat", "surprised"), ("huwaran", "good role model"), ("humuhusay", "getting better"), ("maging", "to become"), ("nasira", "deceased"), ("tututol", "will object"), ("walang kinatatakutan", "fearing no one"), ("iisipin", "will think"), ("lalampa-lampa", "appearing to be weak and feeble"), ("nalaman", "learned"), ("propesyon", "profession")]
