        + [F("Anak, mukhang ___ ka na sa target practice. (getting better)", "humuhusay", ["lumalampa", "tututol"], "humuhusay."), F("Hindi kaya ___ si Nanay sa plano kong maging pulis? (object)", "tututol", ["nagulat", "natanggap"], "tututol."), F("Sana maging ___ ka sa anumang mapili mong propesyon. (role model)", "huwaran", ["kababata", "bagay"], "huwaran."), F("Maging ako ay ___ nung nalaman ko. (surprised)", "nagulat", ["tumutol", "humusay"], "nagulat.")]
